import 'dart:convert';
import 'dart:typed_data';

/// Pre-cached in-memory bytes for Stitch & Witch screenshots and logo
class StitchBytes {
  static final Map<String, Uint8List> _cache = {};

  static Uint8List? getBytes(String assetPath) {
    if (_cache.containsKey(assetPath)) return _cache[assetPath];
    final base64Str = _data[assetPath];
    if (base64Str == null) return null;
    final bytes = base64Decode(base64Str);
    _cache[assetPath] = bytes;
    return bytes;
  }

  static final Map<String, String> _data = {
    'assets/images/stitch_card_banner.png':
        '',
    'assets/images/stitch_logo.png':
        '',
    'assets/images/stitch/stitch_01_bespoke_craftsmanship.png':
        '',
    'assets/images/stitch/stitch_02_master_artisans.png':
        '',
    'assets/images/stitch/stitch_03_delivered_with_care.png':
        '',
    'assets/images/stitch/stitch_04_welcome_auth.png':
        '',
    'assets/images/stitch/stitch_05_client_login.png':
        '',
    'assets/images/stitch/stitch_06_tailor_login.png':
        '',
    'assets/images/stitch/stitch_07_client_home_orders.png':
        '',
    'assets/images/stitch/stitch_08_order_management.png':
        '',
    'assets/images/stitch/stitch_09_category_catalog.png':
        '',
    'assets/images/stitch/stitch_10_client_profile.png':
        '',
    'assets/images/stitch/stitch_11_collection_explore.png':
